function saveRawNewsDatabase(items) {
  try {
    import_fs.default.writeFileSync(RAW_NEWS_DB_FILE, JSON.stringify(items, null, 2), "utf-8");
    return true;
  } catch (e) {
    console.error("Error writing raw_news_database.json:", e);
    return false;
  }
}
